parameters.script:
$src = "C:\Users\me\Desktop\launch-release"
$zip = "C:\Users\me\Desktop\launch-release.zip"
if (-not (Test-Path $src)) { Write-Output "STOP: source folder not found: $src"; exit 1 }
if (Test-Path $zip) { Write-Output "STOP: $zip already exists, not overwriting"; exit 1 }
Compress-Archive -Path "$src\*" -DestinationPath $zip
Add-Type -AssemblyName System.IO.Compression.FileSystem
$a = [System.IO.Compression.ZipFile]::OpenRead($zip)
Write-Output "Archive: $zip ($((Get-Item $zip).Length) bytes)"
$a.Entries | ForEach-Object { Write-Output "ENTRY | $($_.FullName) | $($_.Length) bytes" }
$a.Dispose()
